        ParserOptions options = new ParserOptions();           // independent options object
        options.setAutodetectCharset(autodetectCharset);     // preserve original behaviour
        options.setResolveEntities(false);                    // **critical** – disables XXE

        // Parse using the securely configured options
        Document<T> doc = parser.parse(entityStream, options);

        // Return the root element of the parsed Atom document
        return doc.getRoot();
    }

