public static File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir must not be null");
    if (name == null) throw new IllegalArgumentException("name must not be null");
    // strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Resolve path safely
    Path dirPath = dir.toPath().toAbsolutePath().normalize();
    Path targetPath = dirPath.resolve(name).normalize();

    if (!targetPath.startsWith(dirPath)) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }

    // Use only the file name part for uniqueness handling
    String fileName = targetPath.getFileName().toString();

    // Determine prefix and suffix
    int dot = fileName.lastIndexOf('.'); // use last dot for extension
    String prefix = dot < 0 ? fileName : fileName.substring(0, dot);
    String suffix = dot < 0 ? "" : fileName.substring(dot);
    int index = 2;
    Path candidate = targetPath;
    while (Files.exists(candidate)) {
        String newName = prefix + "-" + index++ + suffix;
        candidate = dirPath.resolve(newName).normalize();
    }

    // Ensure parent directories exist
    Files.createDirectories(candidate.getParent());

    return candidate.toFile();
}

