import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Utility methods for importing files.
 *
 * The {@code allocateFile} method creates a new {@link File} inside a given
 * directory while protecting against directory‑traversal attacks.
 *
 * <p>It sanitises the supplied {@code name}, removes any query part, resolves
 * the path against the target directory and verifies that the resulting
 * canonical path stays inside that directory.  If a file with the same name
 * already exists, a numeric suffix is added (e.g. {@code foo-2.txt}) until a
 * free name is found.  All required parent directories are created.
 *
 * @author  (patched by security review)
 */
public class ImportingUtilities {

    // -----------------------------------------------------------------------
    // other methods …
    // -----------------------------------------------------------------------

    /**
     * Allocates a file inside {@code dir} using the supplied {@code name}.
     *
     * <p>The method is safe against path‑traversal attacks: any attempt to
     * escape {@code dir} (e.g. using {@code "../"} components) results in an
     * {@link IllegalArgumentException}.
     *
     * @param dir  the directory in which the file must be created; must not be {@code null}
     * @param name the requested file name; may contain a query part (e.g. {@code foo.txt?123})
     * @return a {@link File} object that does not yet exist on the file system
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if the resolved path would escape {@code dir}
     * @throws RuntimeException         if the required parent directories cannot be created
     */
    public static File allocateFile(File dir, String name) {
        // -------------------------------------------------------------------
        // Basic argument validation
        // -------------------------------------------------------------------
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // -------------------------------------------------------------------
        // Strip optional query part (e.g. "file.txt?123")
        // -------------------------------------------------------------------
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // -------------------------------------------------------------------
        // Resolve the requested name against the target directory and
        // normalise the resulting path.  This removes any ".." or "." segments.
        // -------------------------------------------------------------------
        Path dirPath   = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // -------------------------------------------------------------------
        // Ensure the resolved path is still inside the intended directory.
        // This blocks directory‑traversal attempts such as "../../etc/passwd".
        // -------------------------------------------------------------------
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Invalid file name: path traversal detected (name = \"" + name + "\")");
        }

        // -------------------------------------------------------------------
        // Work only with the file name part for the uniqueness loop.
        // Using getFileName() guarantees we do not keep any leftover path
        // components that could interfere with the naming logic.
        // -------------------------------------------------------------------
        String fileName = targetPath.getFileName().toString();

        // -------------------------------------------------------------------
        // Split the name into prefix / suffix (extension) – use the last dot
        // so that names like "archive.tar.gz" keep the full extension.
        // -------------------------------------------------------------------
        int dot = fileName.lastIndexOf('.');
        String prefix = (dot < 0) ? fileName : fileName.substring(0, dot);
        String suffix = (dot < 0) ? ""       : fileName.substring(dot);

        // -------------------------------------------------------------------
        // Find a non‑existent file name, appending a numeric suffix when needed.
        // -------------------------------------------------------------------
        Path candidate = targetPath;
        int index = 2;
        while (Files.exists(candidate)) {
            String newName = prefix + "-" + index++ + suffix;
            candidate = dirPath.resolve(newName).normalize();
        }

        // -------------------------------------------------------------------
        // Ensure the parent directory hierarchy exists.
        // Any IOException is wrapped in an unchecked exception because the
        // original method signature does not declare checked exceptions.
        // -------------------------------------------------------------------
        try {
            Files.createDirectories(candidate.getParent());
        } catch (IOException e) {
            throw new RuntimeException("Failed to create directories for " + candidate, e);
        }

        return candidate.toFile();
    }

    // -----------------------------------------------------------------------
    // other methods …
    // -----------------------------------------------------------------------
}
