    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd;

        // Create the SecureRandom instance using the configured algorithm.
        // If the algorithm name is invalid, propagate a clear exception.
        try {
            if (algorithm != null && !algorithm.trim().isEmpty()) {
                rnd = SecureRandom.getInstance(algorithm);
            } else {
                // Fallback to the default constructor which selects a strong algorithm.
                rnd = new SecureRandom();
            }
        } catch (NoSuchAlgorithmException ex) {
            logger.log(Level.SEVERE, "SecureRandom algorithm not available: " + algorithm, ex);
