protected void extractFile(final File srcF, final File dir, final InputStream compressedInputStream,
                           final String entryName, final Date entryDate, final boolean isDirectory,
                           final Integer mode, String symlinkDestination) throws IOException, ArchiverException {
    if (entryName == null) {
        throw new ArchiverException("Entry name is null");
    }

    // Resolve the target file relative to the destination directory
    final File target = FileUtils.resolveFile(dir, entryName);

    // Validate that the resolved file stays inside the destination directory (Zip Slip protection)
    final Path canonicalDirPath = dir.getCanonicalFile().toPath();
    final Path canonicalTargetPath = target.getCanonicalFile().toPath();

    if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
        throw new ArchiverException("Entry is outside of the target directory: " + entryName);
    }

    // Prevent writing over an existing symbolic link when the archive entry is not a symlink
    if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalTargetPath)) {
        throw new ArchiverException("Refusing to overwrite existing symbolic link: " + entryName);
    }

    try {
        if (!isOverwrite() && target.exists() && (target.lastModified() >= entryDate.getTime())) {
            return;
        }

        // Ensure parent directories exist
        final File parent = target.getParentFile();
        if (parent != null) {
