     *   <li>Collapses any number of leading '/' characters to a single '/'.</li>
     *   <li>Handles empty strings and strings consisting solely of '/' by
     *       returning a single '/'.</li>
     * </ul>
     * </p>
     *
     * @param path the raw path component, may be {@code null}
     * @return a normalised path that always begins with a single '/', or {@code null}
     *         if the supplied path was {@code null}
     */
    private static String normalizePath(final String path) {
        if (path == null) {
            return null;
        }

        // Empty input should be treated as the root path.
        if (path.isEmpty()) {
            return "/";
        }

        int firstNonSlash = 0;
        final int len = path.length();

        // Find the index of the first character that is not a '/'.
        while (firstNonSlash < len && path.charAt(firstNonSlash) == '/') {
            firstNonSlash++;
        }

        // If the whole string consists of '/', return a single '/'.
        if (firstNonSlash == len) {
            return "/";
        }

        // Build the normalised path: a single leading '/' followed by the rest.
        return "/" + path.substring(firstNonSlash);
    }

