        while (cb.hasRemaining()) {
            CoderResult res = enc.encode(cb, out, false);

            if (res.isError()) {                     // UNMAPPABLE or MALFORMED
                // ----------------------------------------------------------------
                // Defensive guard – if we keep hitting errors without making
                // progress we abort to avoid a denial‑of‑service situation.
                // ----------------------------------------------------------------
                if (++consecutiveErrorCount > MAX_ERROR_RETRIES) {
                    throw new IllegalStateException(
                            "Too many encoding errors – possible infinite loop");
                }

