    /** Whitelist pattern for locale strings: language or language_country (e.g., "en" or "en_US") */
    private static final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,3}(?:_[a-zA-Z]{2,3})?$");

    // other methods …

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@link String}.  The input is validated
     * against a whitelist to prevent injection attacks.
