        // If the caller already supplied a Locale, trust it.
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // Convert to a trimmed string for validation.
        String localeStr = requestedLocale.toString().trim();

        // Empty strings are not valid locales.
        if (localeStr.isEmpty()) {
            LOG.warn("Requested locale is empty after trimming.");
            return null;
        }

        // Validate against the whitelist pattern.
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
