    /**
     * Creates an {@link LdapContext} using STARTTLS and performs a real bind
     * operation to guarantee that the supplied credentials are validated by the
     * LDAP server.
     *
     * @param ldapContextFactory the factory that provides connection settings
     * @param principal          the LDAP bind DN (must not be {@code null})
     * @param credentials        the password for {@code principal} (must not be {@code null})
     * @return a fully‑initialised {@link LdapContext} that has already been
     *         authenticated over a TLS protected channel
     * @throws NamingException if any LDAP operation fails (including authentication)
     */
    private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                   Object principal,
                                                   Object credentials) throws NamingException {
        // ---- basic argument validation -------------------------------------------------
        if (principal == null) {
            throw new IllegalArgumentException("LDAP principal must not be null");
        }
        if (credentials == null) {
            throw new IllegalArgumentException("LDAP credentials must not be null");
        }

        // ---- extract configuration ------------------------------------------------------
        JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
        Hashtable<String, Object> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
        env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

        // ---- enforce a strong authentication mechanism ---------------------------------
        String authMech = jndiLdapContextFactory.getAuthenticationMechanism();
        if (authMech == null || authMech.trim().isEmpty() || "none".equalsIgnoreCase(authMech)) {
            throw new IllegalArgumentException("Unsupported LDAP authentication mechanism: " + authMech);
        }
        env.put(Context.SECURITY_AUTHENTICATION, authMech);
        env.put(Context.SECURITY_PRINCIPAL, principal);
        env.put(Context.SECURITY_CREDENTIALS, credentials);

        LdapContext ctx = null;
        StartTlsResponse tls = null;
        boolean bindSucceeded = false;

        try {
            // ---- create the initial context (bind will be attempted after TLS) ----------
            ctx = new InitialLdapContext(env, null);

            // ---- start TLS negotiation -------------------------------------------------
            StartTlsRequest startTlsRequest = new StartTlsRequest();
            tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
            tls.negotiate(); // throws IOException on failure

            // ---- force a lightweight LDAP operation to ensure the bind actually succeeds
            //      (e.g. read the root DSE). If the credentials are wrong, a NamingException
            //      will be thrown here.
            ctx.getAttributes("");

            // If we reach this point the authentication is verified.
            bindSucceeded = true;
            return ctx; // TLS channel stays open for the lifetime of the context
        } catch (IOException e) {
            // TLS negotiation failed
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': ",
                    server(jndiLdapContextFactory), e));
            throw new CommunicationException(e.getMessage(), e);
        } catch (NamingException ne) {
            // LDAP bind or any other LDAP operation failed
            LdapUtils.closeContext(ctx);
            securityLog.error(withRealm("LDAP authentication failed for user '%s' on server '%s': ",
                    principal, server(jndiLdapContextFactory), ne));
            throw ne;
        } finally {
            // If the bind did not succeed we must also close the TLS response to avoid
            // leaking resources. When the bind succeeds the TLS channel is kept alive
            // together with the returned context.
            if (!bindSucceeded && tls != null) {
                try {
                    tls.close();
                } catch (IOException ignored) {
                    // ignored – we are already handling a failure
                }
            }
        }
    }
