import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;

public class XsltRenderer implements Renderer {

    // other methods ...

    /**
     * Creates a {@link Transformer} from the supplied XSLT template stream.
     * <p>
     * The method configures a fresh {@link TransformerFactory} with secure
     * processing enabled and disables any access to external DTDs or
     * stylesheets. This prevents malicious XSLT payloads from loading
     * arbitrary resources or executing disallowed extensions.
     *
     * @param templateStream an {@link InputStream} containing a trusted XSLT
     *                       template; must not be {@code null}
     * @return a securely configured {@link Transformer}
     * @throws IOException               if an I/O error occurs while reading the
     *                                   stream
     * @throws ProcessingFailedException  if the XSLT cannot be compiled
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream must not be null");
        }

        // Create a new factory for each call to avoid shared mutable state.
        TransformerFactory factory = TransformerFactory.newInstance();

        // Enable secure processing – this limits the amount of resources the
        // transformer may consume and disables many risky extensions.
        try {
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (TransformerConfigurationException e) {
            // If the implementation does not support the feature we treat it as a
            // configuration error because the security guarantee cannot be met.
            throw new ProcessingFailedException("Unable to enable secure processing for XSLT", e);
        }

        // Disallow any external entity resolution (DTD) and external stylesheet
        // imports/includes. An empty string means “no access”.
        try {
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (IllegalArgumentException | ClassCastException e) {
            // Some JAXP implementations may not support these attributes.
            // In that case we fail fast because the lack of restriction is a
            // security risk.
            throw new ProcessingFailedException("TransformerFactory does not support restricting external resources", e);
        }

        // Use try‑with‑resources to guarantee the InputStream is closed.
        try (InputStream is = templateStream) {
            StreamSource source = new StreamSource(is);
            return factory.newTransformer(source);
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        }
    }

    // other methods ...

}
