    /**
     * Implementation of read for STORED entries.
     *
     * <p>This method has been hardened against malformed ZIP archives that
     * can otherwise cause an infinite read loop.  The original implementation
     * relied on {@code current.bytesRead >= csize} to signal EOF and assumed
     * that {@link InputStream#read(byte[])} would always return a positive
     * number of bytes or {@code -1}.  In practice a crafted stream may return
     * {@code 0} repeatedly, or the declared size may be negative/incorrect.
     * Both situations could lead to an endless loop when the method is used
     * together with {@link java.io.InputStreamReader}.</p>
     *
     * <p>The new implementation:</p>
     * <ul>
     *   <li>Validates the declared size – if it is negative we treat the entry
     *       as having an unknown size and read until the underlying stream
     *       reports EOF.</li>
     *   <li>Detects a zero‑byte read from the underlying stream and treats it
     *       as EOF (or as no progress) to avoid an infinite loop.</li>
     *   <li>Ensures that the buffer is refilled only when necessary and that the
     *       buffer position is correctly reset after each refill.</li>
     *   <li>Accurately caps the number of bytes returned to the caller so
     *       that it never exceeds the declared entry size.</li>
     * </ul>
     *
     * @param buffer the destination buffer
     * @param offset start offset in {@code buffer}
     * @param length maximum number of bytes to read
     * @return the number of bytes read, or {@code -1} if EOF has been reached
     * @throws IOException on I/O error
     */
    private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
        // If the entry uses a data descriptor we have already cached the whole
        // entry in {@code lastStoredEntry}.
        if (current.hasDataDescriptor) {
            if (lastStoredEntry == null) {
                readStoredEntry(); // fills {@code lastStoredEntry}
            }
            return lastStoredEntry.read(buffer, offset, length);
        }

        // Declared size of the entry – may be -1 for malformed archives.
        final long declaredSize = current.entry.getSize();

        // Fast‑path: EOF already reached according to the declared size.
        if (declaredSize >= 0 && current.bytesRead >= declaredSize) {
            return -1;
        }

        int bytesReturned = 0;               // total bytes returned to caller
        int destPos = offset;                // current write position in buffer
        int remaining = length;              // bytes still requested

        while (remaining > 0) {
            // -----------------------------------------------------------------
            // 1. Detect EOF based on declared size (if known)
            // -----------------------------------------------------------------
            if (declaredSize >= 0 && current.bytesRead >= declaredSize) {
                break; // no more data for this entry
            }

            // -----------------------------------------------------------------
            // 2. Ensure the internal buffer contains data
            // -----------------------------------------------------------------
            if (buf.position() >= buf.limit()) {
                // Reset position before refilling
                buf.position(0);
                int read = in.read(buf.array());
                // Treat both -1 (real EOF) and 0 (no progress) as EOF for this entry
                if (read <= 0) {
                    // If we have already returned some bytes, report them;
                    // otherwise propagate EOF.
                    break;
                }
                buf.limit(read);
                count(read);
                current.bytesReadFromStream += read;
            }

            // -----------------------------------------------------------------
            // 3. Determine how many bytes we can safely copy
            // -----------------------------------------------------------------
            int toCopy = Math.min(buf.remaining(), remaining);
            if (declaredSize >= 0) {
                long bytesLeftInEntry = declaredSize - current.bytesRead;
                if (bytesLeftInEntry <= 0) {
                    break; // safety check – should not happen because of step 1
                }
                if (bytesLeftInEntry < toCopy) {
                    toCopy = (int) bytesLeftInEntry;
                }
            }

            // -----------------------------------------------------------------
            // 4. Copy the data
            // -----------------------------------------------------------------
            buf.get(buffer, destPos, toCopy);
            destPos += toCopy;
            remaining -= toCopy;
            bytesReturned += toCopy;
            current.bytesRead += toCopy;

            // If we copied less than requested because the entry is exhausted,
            // exit the loop – the next call will return -1.
            if (declaredSize >= 0 && current.bytesRead >= declaredSize) {
                break;
            }
