        if (bytesReturned == 0 && (declaredSize >= 0 && current.bytesRead >= declaredSize)) {
            return -1;
        }
        // If nothing was read and the underlying stream signaled EOF, also return -1.
        if (bytesReturned == 0 && (buf.position() >= buf.limit())) {
            return -1;
        }
