final static private XMLStreamReader createXMLStreamReader(InputStream inputStream) throws XMLStreamException, IOException {
    if (inputStream == null) {
        throw new IllegalArgumentException("inputStream must not be null");
    }

    XMLInputFactory factory = XMLInputFactory.newInstance();

    // Harden the factory against XXE attacks
    // Disable DTDs entirely
    try {
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
    } catch (IllegalArgumentException e) {
        // If the implementation does not support the property, fail fast
        throw new XMLStreamException("XML parser does not support disabling DTDs", e);
    }

    // Disallow external entities
    try {
        factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
    } catch (IllegalArgumentException e) {
        throw new XMLStreamException("XML parser does not support disabling external entities", e);
    }

    // The following properties are safe and improve usability
    factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
    factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);
    // Ensure namespace awareness (required for most XML processing)
    factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);

    // Create the reader using a stream that strips any unwanted XML prefix
    return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
}
