import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Helper that decides whether a self‑service update request for a {@link ScimUser}
 * is allowed. The method now enforces that the caller is authenticated and
 * that the caller is the owner of the account being modified.  All field
 * comparisons are performed safely (null‑aware) and the method returns {@code false}
 * for any unauthorized or malformed request.
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming HTTP request is allowed to update the
     * user identified by the path variable. The caller must be authenticated
     * and must match the user id in the URL.  In addition, the request body
     * must not attempt to change immutable or privileged fields (email,
     * username, origin, verification status, active flag) without matching
     * the current persisted values.
     *
     * @param request the incoming servlet request
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        /* -------------------------------------------------------------
         * 1. Verify authentication and ownership
         * ------------------------------------------------------------- */
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated principal – deny the request
            return false;
        }
        String authenticatedUserId = principal.getName(); // assumed to be the SCIM user id
        String pathUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // The caller must be updating *their own* record
        if (!Objects.equals(authenticatedUserId, pathUserId)) {
            return false;
        }

        /* -------------------------------------------------------------
         * 2. Load the persisted user (if it exists)
         * ------------------------------------------------------------- */
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(pathUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot validate the update – deny.
            // (Returning true here would allow creation of arbitrary users.)
            return false;
        }

        /* -------------------------------------------------------------
         * 3. Parse the incoming payload
         * ------------------------------------------------------------- */
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            return false;
        }

        /* -------------------------------------------------------------
         * 4. Perform strict field equality checks.
         *    Any deviation (including null mismatches) results in denial.
         * ------------------------------------------------------------- */
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    // other methods (unchanged)
}
